assessment = params.get("assessment") or {}
if not isinstance(assessment, dict):
    assessment = {}
value = params.get("estimated_value") or {}
if not isinstance(value, dict):
    value = {"amount": value}
reported = params.get("missing") or []
if isinstance(reported, str):
    reported = [reported]


def as_number(raw, fallback):
    try:
        return float(raw)
    except (TypeError, ValueError):
        return fallback


threshold = as_number(params.get("min_score"), 60.0)
fit_points = {"strong": 30, "partial": 15, "weak": 5}
need_points = {"urgent": 25, "clear": 18, "vague": 6}
budget_points = {"confirmed": 25, "indicative": 12, "none": 0}
timeline_points = {"this_quarter": 20, "next_quarter": 12, "later": 4}
labels = {"fit": "Fit with what we sell", "need": "Stated need", "budget": "Budget", "timeline": "Buying timeline"}
tables = {"fit": fit_points, "need": need_points, "budget": budget_points, "timeline": timeline_points}

points = 0
reasons = []
missing = []
for key in ["fit", "need", "budget", "timeline"]:
    answer = str(assessment.get(key) or "unknown").strip().lower()
    gained = tables[key].get(answer)
    if gained is None:
        missing.append(labels[key])
        reasons.append(labels[key] + ": not known yet (0 points)")
    else:
        points += gained
        reasons.append(labels[key] + ": " + answer.replace("_", " ") + " (" + str(gained) + " points)")

if assessment.get("decisionMaker") is True:
    points += 5
    reasons.append("Spoke with the decision maker (5 points)")

amount = as_number(value.get("amount"), 0.0)
if amount >= 20000:
    points += 5
    reasons.append("Estimated value of " + str(int(amount)) + " is above 20,000 (5 points)")

score = int(min(points, 100))
band = "hot" if score >= 75 else ("warm" if score >= 50 else "cold")
qualifies = score >= threshold
for note in reported:
    text = str(note).strip()
    if text and text not in missing:
        missing.append(text)
